#include "greeter.grpc.pb.h"
// Generated by default even though messages.proto has no service.
#include "messages.grpc.pb.h"
#include "plain/plain.pb.h"

#include <grpcpp/grpcpp.h>

#include <iostream>
#include <string>

class GreeterImpl final : public Greeter::Service
{
    grpc::Status SayHello(grpc::ServerContext *, const HelloRequest *request, HelloReply *reply) override
    {
        reply->set_message("Hello " + request->name());
        return grpc::Status::OK;
    }
};

int main(int argc, char **argv)
{
    GOOGLE_PROTOBUF_VERIFY_VERSION;

    // Call the service implementation directly: no server or network needed,
    // but the generated .grpc.pb.cc must be compiled and linked.
    GreeterImpl service;

    HelloRequest request;
    request.set_name("world");
    HelloReply reply;
    grpc::ServerContext context;
    grpc::Status status = static_cast<Greeter::Service &>(service).SayHello(&context, &request, &reply);

    Plain plain;
    plain.set_value("plain");

    bool ok = status.ok() && reply.message() == "Hello world" && plain.value() == "plain";
    if (!ok)
        std::cerr << "unexpected reply '" << reply.message() << "'" << std::endl;

    google::protobuf::ShutdownProtobufLibrary();
    return ok ? 0 : 1;
}
